<?php
declare(strict_types=1);
function pricing_compute(array $estimate,?string $override=null):array{
 $packages=json_decode($estimate['packages_json'],true,512,JSON_THROW_ON_ERROR);$policy=crm_query('SELECT * FROM nd_pricing_policies ORDER BY id DESC LIMIT 1'.(db()->inTransaction()?' FOR UPDATE':''))->fetch()?:null;
 $r=['estimate_id'=>(int)$estimate['id'],'project_id'=>(int)$estimate['project_id'],'scope'=>json_decode($estimate['scope_json'],true),'packages'=>$packages,'policy'=>$policy,'rates'=>[],'components'=>[],'missing'=>[],'warnings'=>[],'currency'=>'RUB','direct_minor'=>null,'overhead_minor'=>null,'contingency_minor'=>null,'cost_pool_minor'=>null,'recommended_minor'=>null,'selling_minor'=>null,'tax_minor'=>null,'payment_fee_minor'=>null,'contribution_minor'=>null,'owner_override'=>$override!==null,'owner_requested_price_minor'=>$override===null?null:bill_minor($override),'profitability'=>'NEEDS_COST_REVIEW'];
 if(!($r['scope']['requirements_present']??false))$r['missing'][]='Недостаточно подтверждённых требований проекта.';
 if(!$policy||!$policy['approved']||$policy['tax_method']==='unknown'||$policy['tax_bp']===null)$r['missing'][]='Не утверждены налоговая трактовка и правила доходности.';
 if(hash('sha256',ai_json(pricing_scope((int)$estimate['project_id'])))!==$estimate['scope_hash'])$r['missing'][]='Состав проекта изменился: требуется новая оценка, а не повтор старого расчёта.';
 $mapping=['development_hours'=>'labor_hour','testing_hours'=>'labor_hour','ai_input_tokens'=>'ai_input_1000','ai_output_tokens'=>'ai_output_1000','hosting_months'=>'hosting_month','tool_units'=>'tool_unit','external_units'=>'external_unit','other_units'=>'other_unit'];$direct=0;
 foreach($packages as $n=>$p){if($p['uncertain'])$r['warnings'][]='Пакет «'.$p['name'].'»: величины являются оценками.';if($p['risk']==='high')$r['warnings'][]='Высокий риск: '.$p['name'];
  foreach($mapping as $field=>$category){$q=$p[$field];if($q===null){$r['missing'][]=$p['name'].': неизвестно '.$field;$r['components'][]=['package'=>$n,'kind'=>$field,'category'=>$category,'quantity'=>null,'cost_minor'=>null];continue;}$milli=bill_minor($q,3);if($milli===0){$r['components'][]=['package'=>$n,'kind'=>$field,'category'=>$category,'quantity'=>$q,'cost_minor'=>0,'basis'=>'Явно заданный нулевой расход, не неизвестное значение.'];continue;}
   $rate=pricing_rate($category);if(!$rate||$rate['currency']!=='RUB'){$r['missing'][]='Нет действующей ставки RUB: '.$category;$r['components'][]=['package'=>$n,'kind'=>$field,'category'=>$category,'quantity'=>$q,'cost_minor'=>null];continue;}$r['rates'][$category]=$rate;
   // quantity_milli for tokens is divided by 1000 again because rates are per 1000 tokens.
   $denom=str_starts_with($category,'ai_')?1000000:1000;$adjusted=in_array($field,['development_hours','testing_hours'],true)&&$policy?pricing_ceil($milli*(int)$policy['effort_factor_bp'],10000):$milli;$product=$adjusted*(int)$rate['value_scaled'];if(!is_int($product)||$product>PHP_INT_MAX-500000)crm_fail(422,'Оценка выходит за допустимые пределы.');$cost=intdiv($product+intdiv($denom,2),$denom);$direct+=$cost;if($direct>9999999999)crm_fail(422,'Слишком большая стоимость проекта.');$r['components'][]=['package'=>$n,'kind'=>$field,'category'=>$category,'quantity'=>$q,'rate_id'=>(int)$rate['id'],'adjusted_quantity_milli'=>$adjusted,'cost_minor'=>$cost];
  }
 }
 $fee=pricing_rate('payment_fee_percent');if(!$fee||$fee['currency']!=='RUB')$r['missing'][]='Не настроена комиссия оплаты; нулевая комиссия должна быть задана явно.';else $r['rates']['payment_fee_percent']=$fee;
 if($r['missing'])return $r;
 $overhead=pricing_ceil($direct*(int)$policy['overhead_bp'],10000);$contingency=pricing_ceil(($direct+$overhead)*(int)$policy['contingency_bp'],10000);$pool=$direct+$overhead+$contingency;
 $feeBp=(int)$fee['value_scaled'];$taxBp=(int)$policy['tax_bp'];$margin=(int)$policy['margin_bp'];$denom=10000-$feeBp-$taxBp-$margin;if($denom<1){$r['missing'][]='Комиссии, налог и маржа не оставляют положительной базы цены.';return $r;}
 $recommended=pricing_ceil($pool*10000,$denom);for($i=0;$i<5;$i++){if($recommended-pricing_ceil($recommended*$feeBp,10000)-pricing_ceil($recommended*$taxBp,10000)-$pool>=pricing_ceil($recommended*$margin,10000))break;$recommended++;}
 $price=$override===null?$recommended:bill_minor($override);if($price<0||$price>9999999999)crm_fail(422,'Цена должна быть положительной и укладываться в лимит счетов.');$tax=pricing_ceil($price*$taxBp,10000);$payment=pricing_ceil($price*$feeBp,10000);$profit=$price-$tax-$payment-$pool;
 $r=array_replace($r,['direct_minor'=>$direct,'overhead_minor'=>$overhead,'contingency_minor'=>$contingency,'cost_pool_minor'=>$pool,'recommended_minor'=>$recommended,'selling_minor'=>$price,'tax_minor'=>$tax,'payment_fee_minor'=>$payment,'contribution_minor'=>$profit,'profitability'=>$profit<0?'LOSS':($profit*10000<$price*(int)$policy['minimum_bp']?'BELOW_MINIMUM':'ACCEPTABLE')]);if($r['profitability']!=='ACCEPTABLE')$r['warnings'][]='Цена не проходит утверждённый минимум доходности.';return $r;
}
function pricing_quote(array $estimate,?string $override=null,?int $replaces=null):array{
 pricing_scope((int)$estimate['project_id'],true);$r=pricing_compute($estimate,$override);$n=(int)crm_query('SELECT COALESCE(MAX(revision_number),0) FROM nd_quotations WHERE project_id=?',[$estimate['project_id']])->fetchColumn()+1;$json=ai_json($r);$state=$r['missing']||$r['profitability']!=='ACCEPTABLE'?'NEEDS_COST_REVIEW':'DRAFT';
 crm_query('INSERT INTO nd_quotations(project_id,estimate_id,revision_number,policy_id,calculation_json,checksum,state,replaces_id) VALUES (?,?,?,?,?,?,?,?)',[$estimate['project_id'],$estimate['id'],$n,$r['policy']['id']??null,$json,hash('sha256',$json),$state,$replaces]);$id=(int)db()->lastInsertId();crm_notice('pricing:quote:'.$id,'projects',(int)$estimate['project_id'],$state==='DRAFT'?'Расчёт цены готов к согласованию':'Требуется проверка затрат проекта');return pricing_detail($id);
}
function pricing_detail(int $id,bool $lock=false):array{$q=crm_query('SELECT * FROM nd_quotations WHERE id=?'.($lock?' FOR UPDATE':''),[$id])->fetch();if(!$q)crm_fail(404,'Расчёт не найден.');if(!hash_equals($q['checksum'],hash('sha256',$q['calculation_json'])))crm_fail(409,'Снимок расчёта повреждён.');$q['calculation']=json_decode($q['calculation_json'],true);unset($q['calculation_json']);return $q;}
function pricing_fresh(array $q):bool{
 $r=$q['calculation'];try{$currentScope=pricing_scope((int)$q['project_id']);}catch(CrmFailure $e){if(in_array($e->status,[404,409],true))return false;throw $e;}if(hash('sha256',ai_json($currentScope))!==hash('sha256',ai_json($r['scope']))){require_once dirname(__DIR__).'/catalog/bindings.php';if(!cat_quote_scope_matches($q,$currentScope))return false;}$policy=crm_query('SELECT id FROM nd_pricing_policies ORDER BY id DESC LIMIT 1'.(db()->inTransaction()?' FOR UPDATE':''))->fetchColumn();if((int)$policy!==(int)$q['policy_id'])return false;
 foreach($r['rates'] as $category=>$old){$current=pricing_rate($category);if(!$current||(int)$current['id']!==(int)$old['id'])return false;}return true;
}
function pricing_require_approved(int $project):array{
 pricing_gate();$q=crm_query('SELECT id FROM nd_quotations WHERE project_id=? ORDER BY revision_number DESC LIMIT 1',[$project])->fetchColumn();if(!$q)crm_fail(409,'NEEDS_COST_REVIEW: нет согласованного расчёта цены.');$q=pricing_detail((int)$q);if($q['state']!=='APPROVED'||!pricing_fresh($q))crm_fail(409,'NEEDS_COST_REVIEW: расчёт изменился или ещё не одобрен.');return $q;
}
function pricing_proposal_text(array $o,array $q):string{
 $r=$o['result'];$price=bill_decimal((int)$q['calculation']['selling_minor']);$body="Предложение НейроДело. Цена по одобренному расчёту №".$q['id'].': '.$price." RUB.\n\n".$r['needs']."\n".$r['solution']."\nОбъём:\n".implode("\n",$r['scope'])."\nРезультаты:\n".implode("\n",$r['deliverables'])."\n\nСроки и дополнительные условия требуют отдельного подтверждения владельцем.";if(mb_strlen($body)>5000)crm_fail(422,'Предложение слишком большое для безопасной отправки.');return $body;
}
function pricing_insights():array{
 $rows=crm_query('SELECT a.*,q.calculation_json FROM nd_project_actuals a JOIN nd_quotations q ON q.id=a.quotation_id WHERE a.id=(SELECT MAX(b.id) FROM nd_project_actuals b WHERE b.quotation_id=a.quotation_id) ORDER BY a.id DESC LIMIT 100')->fetchAll();$estimatedHours=0;$actualHours=0;$delta=0;
 foreach($rows as $r){$q=json_decode($r['calculation_json'],true);foreach($q['packages'] as $p){if($p['development_hours']!==null)$estimatedHours+=bill_minor($p['development_hours'],3);if($p['testing_hours']!==null)$estimatedHours+=bill_minor($p['testing_hours'],3);}$actualHours+=(int)$r['development_milli']+(int)$r['testing_milli'];$delta+=(int)$r['actual_cost_minor']-(int)$q['cost_pool_minor']-(int)$q['tax_minor']-(int)$q['payment_fee_minor'];}
 return ['ok'=>true,'sample_count'=>count($rows),'cost_delta_minor'=>$rows?$delta:null,'suggested_effort_factor_bp'=>$estimatedHours>0?pricing_ceil($actualHours*10000,$estimatedHours):null,'applied'=>false,'meaning'=>'По последним подтверждённым владельцем итогам, до 100 расчётов. Поправка не применяется автоматически: нужна новая одобренная политика. Исторические цены не меняются.'];
}
